const items = $input.all();

return items.map((item, index) => {
  const data = item.json.body ?? item.json;
  const errors = [];

  const name = String(
    data.fullName ?? ""
  ).trim().replace(/\s+/g, " ");

  const email = String(
    data.emailAddress ?? ""
  ).trim().toLowerCase();

  const phone = String(
    data.phoneNumber ?? ""
  ).trim();

  const company = String(
    data.organization ?? ""
  ).trim();

  const service = String(
    data.serviceInterested ?? ""
  ).trim();

  const budgetInput = data.estimatedBudget;

  const budget =
    budgetInput === "" ||
    budgetInput == null
      ? null
      : Number(budgetInput);

  const sourceEventId = String(
    data.submissionId ?? ""
  ).trim();

  const message = String(
    data.projectDescription ?? ""
  ).trim();

  const emailPattern =
    /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  if (!sourceEventId) {
    errors.push("submissionId is required");
  }

  if (name.length < 2) {
    errors.push("Invalid customer name");
  }

  if (!emailPattern.test(email)) {
    errors.push("Invalid email address");
  }

  if (
    budget !== null &&
    (!Number.isFinite(budget) || budget < 0)
  ) {
    errors.push("Invalid estimated budget");
  }

  return {
    json: {
      source: "website",
      source_event_id: sourceEventId,

      customer: {
        name,
        email,
        phone,
        company
      },

      inquiry: {
        service,
        budget,
        message
      },

      validation: {
        is_valid: errors.length === 0,
        errors
      }
    },
    pairedItem: { item: index }
  };
});

